function daysUntil(ty,tm,td, fy,fm,fd){ if(fy==null){ var n=new Date(); fy=n.getFullYear(); fm=n.getMonth()+1; fd=n.getDate(); }
  return diffDays(fy,fm,fd, ty,tm,td); }
var EXPORTS={diffDays:diffDays, daysUntil:daysUntil};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DaysUntilForgePure = EXPORTS; }
